// cspell: words unifold Unifold
import { useIntl } from 'react-intl';

import {
  DashText,
  Icon,
  QRCode,
  SizableText,
  Skeleton,
  Stack,
  XStack,
  YStack,
  useClipboard,
} from '@onekeyhq/components';
import { HighlightAddress } from '@onekeyhq/kit/src/components/HighlightAddress';
import { Token } from '@onekeyhq/kit/src/components/Token';
import {
  UNIFOLD_HELP_URL,
  UNIFOLD_TERMS_URL,
} from '@onekeyhq/kit/src/views/Perp/consts/unifold';
import { ETranslations } from '@onekeyhq/shared/src/locale';
import { openUrlExternal } from '@onekeyhq/shared/src/utils/openUrlUtils';

import { normalizeUnifoldIconUrl } from './unifoldFormat';

const QR_CANVAS_SIZE = 200;
const QR_CARD_BORDER_WIDTH = 1;
const QR_CARD_SIZE = QR_CANVAS_SIZE + QR_CARD_BORDER_WIDTH * 2;
const QR_CODE_PADDING = 10;
const QR_CODE_SIZE = QR_CANVAS_SIZE - QR_CODE_PADDING;
const QR_QUIET_ZONE_MODULES = 2;
const QR_LOGO_SIZE = 56;
const QR_LOGO_MARGIN = 4;

// "Intent address" QR block. Deviation from the SDK (documented in the plan):
// OneKey's QRCode always renders on an opaque light plate so it stays
// scannable in dark mode; the SDK's transparent-background QR is not
// replicated. The center logo is the selected chain icon, like the SDK.
export function UnifoldDepositQRCard({
  address,
  chainIconUri,
  loading,
  sourceTokenSymbol,
  sourceTokenIconUri,
  receiveTokenSymbol,
  receiveTokenIconUri,
  receiveNetworkIconUri,
  showConversionRoute = true,
}: {
  address: string | null;
  chainIconUri?: string;
  loading: boolean;
  sourceTokenSymbol?: string;
  sourceTokenIconUri?: string;
  receiveTokenSymbol?: string;
  receiveTokenIconUri?: string;
  receiveNetworkIconUri?: string;
  showConversionRoute?: boolean;
}) {
  const intl = useIntl();
  const { copyText } = useClipboard();
  const normalizedChainIconUri = normalizeUnifoldIconUrl(chainIconUri);
  const shouldShowConversionRoute = Boolean(
    showConversionRoute &&
    (address || loading) &&
    sourceTokenSymbol &&
    receiveTokenSymbol,
  );

  return (
    <YStack
      testID="perps-unifold-deposit-qr-card"
      pt="$3"
      alignItems="center"
      gap="$6"
    >
      {!loading && !address ? (
        <YStack
          width={QR_CARD_SIZE}
          height={QR_CARD_SIZE}
          alignItems="center"
          justifyContent="center"
          gap="$2"
        >
          <Stack
            width="$10"
            height="$10"
            borderRadius="$full"
            bg="$bgInfoSubdued"
            alignItems="center"
            justifyContent="center"
          >
            <Icon name="InfoCircleOutline" size="$5" color="$iconInfo" />
          </Stack>
          <SizableText size="$bodyMdMedium" color="$text">
            {intl.formatMessage({
              id: ETranslations.perp_unifold_address_unavailable__title,
            })}
          </SizableText>
          <SizableText
            size="$bodySm"
            color="$textSubdued"
            textAlign="center"
            maxWidth="$48"
          >
            {intl.formatMessage({
              id: ETranslations.perp_unifold_choose_another_asset_network__desc,
            })}
          </SizableText>
        </YStack>
      ) : null}
      {loading ? (
        <Skeleton width={QR_CARD_SIZE} height={QR_CARD_SIZE} radius={8} />
      ) : null}
      {!loading && address ? (
        <Stack
          testID="perps-unifold-qr-visual"
          width={QR_CARD_SIZE}
          height={QR_CARD_SIZE}
          borderWidth={QR_CARD_BORDER_WIDTH}
          borderColor="$borderSubdued"
          borderRadius="$2"
          overflow="hidden"
          // same color as the QR plate: the plate's own corner rounding is
          // larger than this card's, so without a matching backdrop the modal
          // background pokes through as dark wedges at the four corners
          bg="white"
        >
          <QRCode
            value={address}
            size={QR_CODE_SIZE}
            padding={QR_CODE_PADDING}
            quietZoneModules={QR_QUIET_ZONE_MODULES}
            logo={
              normalizedChainIconUri
                ? { uri: normalizedChainIconUri }
                : undefined
            }
            logoSize={QR_LOGO_SIZE}
            logoMargin={QR_LOGO_MARGIN}
            logoBackgroundColor="white"
          />
        </Stack>
      ) : null}
      {shouldShowConversionRoute ? (
        <XStack
          testID="perps-unifold-conversion-route"
          width="auto"
          maxWidth="100%"
          minHeight="$12"
          px="$4"
          py="$1.5"
          alignItems="center"
          justifyContent="center"
          gap="$3"
          bg="$bgStrong"
          borderRadius="$full"
        >
          <XStack flexShrink={1} minWidth={0} alignItems="center" gap="$2">
            <Token
              size="sm"
              tokenImageUri={normalizeUnifoldIconUrl(sourceTokenIconUri)}
              networkImageUri={normalizedChainIconUri}
            />
            <YStack minWidth={0}>
              <SizableText size="$bodyXs" color="$textSubdued">
                {intl.formatMessage({
                  id: ETranslations.perp_unifold_you_send__title,
                })}
              </SizableText>
              <SizableText size="$bodySmMedium" color="$text" numberOfLines={1}>
                {sourceTokenSymbol}
              </SizableText>
            </YStack>
          </XStack>
          <Icon
            name="ArrowRightOutline"
            size="$5"
            color="$iconDisabled"
            flexShrink={0}
          />
          <XStack flexShrink={1} minWidth={0} alignItems="center" gap="$2">
            <Token
              size="sm"
              tokenImageUri={normalizeUnifoldIconUrl(receiveTokenIconUri)}
              networkImageUri={normalizeUnifoldIconUrl(receiveNetworkIconUri)}
            />
            <YStack minWidth={0}>
              <SizableText size="$bodyXs" color="$textSubdued">
                {intl.formatMessage({
                  id: ETranslations.swap_review_you_receive,
                })}
              </SizableText>
              <SizableText size="$bodySmMedium" color="$text" numberOfLines={1}>
                {receiveTokenSymbol}
              </SizableText>
            </YStack>
          </XStack>
        </XStack>
      ) : null}
      {/* Hidden entirely when there is no address to show and none is coming:
            a shimmering skeleton under the "No address available" plate would
            contradict it, in a row that still looks pressable. */}
      {address || loading ? (
        <YStack width="100%" gap="$2">
          <XStack
            width="100%"
            maxWidth="100%"
            alignItems="center"
            justifyContent="space-between"
            gap="$2"
          >
            <XStack flex={1} minWidth={0}>
              <DashText
                size="$bodySm"
                color="$textSubdued"
                dashColor="$textDisabled"
                dashThickness={0.5}
                tooltip={intl.formatMessage({
                  id: ETranslations.perp_unifold_deposit_address_conversion__desc,
                })}
                tooltipTitle={intl.formatMessage({
                  id: ETranslations.perp_unifold_your_deposit_address__title,
                })}
                tooltipPlacement="bottom-start"
              >
                {intl.formatMessage({
                  id: ETranslations.perp_unifold_your_deposit_address__title,
                })}
              </DashText>
            </XStack>
            <XStack alignItems="center" gap="$2" flexShrink={0}>
              <SizableText
                testID="perps-unifold-terms"
                size="$bodySm"
                color="$textInfo"
                role="link"
                cursor="pointer"
                userSelect="none"
                hoverStyle={{ color: '$textInfoStrong' }}
                pressStyle={{ color: '$textInfoStrong' }}
                onPress={() => openUrlExternal(UNIFOLD_TERMS_URL)}
              >
                {intl.formatMessage({
                  id: ETranslations.perp_unifold_terms__action,
                })}
              </SizableText>
              <SizableText
                testID="perps-unifold-help"
                size="$bodySm"
                color="$textInfo"
                role="link"
                cursor="pointer"
                userSelect="none"
                hoverStyle={{ color: '$textInfoStrong' }}
                pressStyle={{ color: '$textInfoStrong' }}
                onPress={() => openUrlExternal(UNIFOLD_HELP_URL)}
              >
                {intl.formatMessage({
                  id: ETranslations.menu_help,
                })}
              </SizableText>
            </XStack>
          </XStack>
          {address ? (
            <XStack
              testID="perps-unifold-copy-deposit-address"
              width="100%"
              px="$3"
              py="$4"
              gap="$3"
              alignItems="flex-start"
              bg="$bgStrong"
              borderRadius="$3"
              role="button"
              cursor="pointer"
              userSelect="none"
              hoverStyle={{ bg: '$bgStrongHover' }}
              pressStyle={{ bg: '$bgStrongActive' }}
              onPress={() => copyText(address)}
              focusable
              focusVisibleStyle={{
                outlineWidth: 2,
                outlineColor: '$focusRing',
                outlineOffset: 2,
                outlineStyle: 'solid',
              }}
            >
              <XStack flex={1} flexWrap="wrap">
                <HighlightAddress
                  address={address}
                  size="$bodyMd"
                  fontFamily="$monoRegular"
                />
              </XStack>
              <Stack mt="$0.5" flexShrink={0}>
                <Icon name="Copy3Outline" size="$5" color="$iconSubdued" />
              </Stack>
            </XStack>
          ) : null}
          {!address && loading ? (
            <Skeleton width="100%" height={64} borderRadius="$3" />
          ) : null}
        </YStack>
      ) : null}
    </YStack>
  );
}
